import os
import re
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageOps


IMG_DIR = "/app/workspace/dataset/img"
OUTPUT_XLSX = "/app/workspace/stat_ocr.xlsx"

# Priority groups: most specific first.
PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

# These are excluded only when they are the "primary" descriptor on the line.
TAX_KEYWORDS = ["TAX", "GST", "SST"]


NUMBER_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})(?![\w.])")


def ocr_variants(image_path):
    """Return a list of OCR text strings using multiple configurations."""
    img = Image.open(image_path)
    gray = img.convert("L")
    autocontrast = ImageOps.autocontrast(gray)

    variants = []
    for src in (img, gray, autocontrast):
        for psm in (3, 4, 6):
            try:
                text = pytesseract.image_to_string(src, config=f"--psm {psm}")
                variants.append(text)
            except Exception:
                pass
    return variants


def parse_date(text):
    """Return ISO date string if any date-like substring is found, else None."""
    patterns = [
        # DD/MM/YYYY or DD-MM-YYYY
        (r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b", "dmy"),
        # DD/MM/YY or DD-MM-YY
        (r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b", "dmy2"),
        # YYYY-MM-DD or YYYY/MM/DD
        (r"\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b", "ymd"),
    ]
    for pat, fmt in patterns:
        for match in re.finditer(pat, text):
            try:
                if fmt == "dmy":
                    d, m, y = int(match.group(1)), int(match.group(2)), int(match.group(3))
                elif fmt == "dmy2":
                    d, m, y = int(match.group(1)), int(match.group(2)), 2000 + int(match.group(3))
                else:
                    y, m, d = int(match.group(1)), int(match.group(2)), int(match.group(3))
                if 1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
                    return f"{y:04d}-{m:02d}-{d:02d}"
            except ValueError:
                continue
    return None


def line_has_exclusion(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def line_has_tax_as_primary(line_upper):
    """Treat TAX/GST/SST as primary descriptor if they are not inside parentheses
    and immediately follow TOTAL/AMOUNT without additional qualifier words."""
    # Remove parenthesized content
    stripped = re.sub(r"\([^)]*\)", "", line_upper)
    # Check for patterns like "TOTAL GST", "TOTAL TAX", "GST SUMMARY"
    for kw in TAX_KEYWORDS:
        # "TOTAL GST", "TOTAL TAX" exactly
        if re.search(rf"\bTOTAL\s+{kw}\b", stripped):
            return True
        # Line starts with the tax keyword like "GST Payable", "GST Summary"
        if re.search(rf"^\s*{kw}\b", stripped):
            return True
        # Line ends with just the tax keyword before the number
        # like "...  TOTAL TAX :  1.02" - already covered above
    return False


def extract_amount_from_line(line):
    """Return the last decimal number on the line, as a float, or None."""
    matches = NUMBER_RE.findall(line)
    if not matches:
        return None
    val = matches[-1].replace(",", "")
    try:
        return float(val)
    except ValueError:
        return None


def extract_total_from_text(text):
    """Return the total amount as a float, or None."""
    lines = text.split("\n")
    uppers = [ln.upper() for ln in lines]

    for group in PRIORITY_KEYWORDS:
        matched_lines = []
        for idx, u in enumerate(uppers):
            # Does any keyword in this priority group match?
            matched_kw = None
            for kw in group:
                if kw in u:
                    matched_kw = kw
                    break
            if not matched_kw:
                continue
            if line_has_exclusion(u):
                continue
            if line_has_tax_as_primary(u):
                continue
            matched_lines.append((idx, lines[idx]))

        if not matched_lines:
            continue

        # Prefer the LAST matching line (final total near end of receipt)
        idx, line = matched_lines[-1]
        amt = extract_amount_from_line(line)
        if amt is None and idx + 1 < len(lines):
            # Fallback: use last number on next line
            amt = extract_amount_from_line(lines[idx + 1])
        if amt is not None:
            return amt
    return None


def extract_fields(image_path):
    """Combine OCR variants to extract date and total."""
    variants = ocr_variants(image_path)

    # Pick the first non-None date and total across variants, preferring default PSM
    date = None
    for text in variants:
        d = parse_date(text)
        if d is not None:
            date = d
            break

    totals = []
    for text in variants:
        t = extract_total_from_text(text)
        if t is not None:
            totals.append(t)

    total = None
    if totals:
        # Pick the most common value, or the first if all unique.
        from collections import Counter
        counter = Counter(totals)
        total, _ = counter.most_common(1)[0]

    return date, total


def main():
    results = []
    for img_file in sorted(Path(IMG_DIR).iterdir()):
        if img_file.suffix.lower() not in {".jpg", ".jpeg", ".png"}:
            continue
        date, total = extract_fields(str(img_file))
        if total is not None:
            total_str = f"{total:.2f}"
        else:
            total_str = None
        results.append((img_file.name, date, total_str))
        print(f"{img_file.name}: date={date}, total={total_str}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for filename, date, total in results:
        ws.append([filename, date, total])
    wb.save(OUTPUT_XLSX)
    print(f"\nSaved to {OUTPUT_XLSX}")


if __name__ == "__main__":
    main()
"}

