import os
import re
from collections import Counter
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageOps


IMG_DIR = "/app/workspace/dataset/img"
OUTPUT_XLSX = "/app/workspace/stat_ocr.xlsx"


PRIORITY_KEYWORDS = [
    [r"GRAND\s+TOTAL"],
    [r"TOTAL\s*RM", r"TOTAL\s*:\s*RM"],
    [r"TOTAL\s+AMOUNT"],
    [r"TOTAL", r"AMOUNT", r"BALANCE\s*DUE", r"NETT\s*TOTAL", r"NET\s*TOTAL"],
]

EXCLUSION_PATTERNS = [
    r"SUBTOTAL",
    r"SUB[-\s]?TOTAL",
    r"DISCOUNT",
    r"\bCHANGE\b",
    r"CASH\s*TENDERED",
]

TAX_PRIMARY_PATTERNS = [
    r"TOTAL\s*(?:GST|TAX|SST)\b",   # "Total GST", "TotalGST"
    r"^\s*(?:GST|TAX|SST)\b",       # Line starts with GST/TAX/SST
    r"\bGST\s+SUMMARY\b",
    r"\bTAX\s+SUMMARY\b",
    r"\bTAX\s+CODE\b",
    r"\bTAX\s+INVOICE\b",
    r"\bGST\s+PAYABLE\b",
]

GST_SUMMARY_HEADER = re.compile(r"GST\s*SUMMARY|TAX\s*SUMMARY", re.IGNORECASE)

NUMBER_RE = re.compile(r"(?<![\d.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?!\d)")


def ocr_variants(image_path):
    """Generate OCR text using multiple configurations."""
    img = Image.open(image_path)
    gray = img.convert("L")
    autocontrast = ImageOps.autocontrast(gray)
    upscale = img.resize((img.width * 2, img.height * 2))

    configs = [
        (img, 3),
        (img, 4),
        (img, 6),
        (gray, 6),
        (autocontrast, 6),
        (upscale, 6),
    ]
    variants = []
    for src, psm in configs:
        try:
            text = pytesseract.image_to_string(src, config=f"--psm {psm}")
            variants.append(text)
        except Exception:
            pass
    return variants


def parse_date(text):
    """Return ISO date string if any date-like substring is found, else None."""
    patterns = [
        (r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b", "dmy"),
        (r"\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b", "ymd"),
        (r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b", "dmy2"),
    ]
    for pat, fmt in patterns:
        for match in re.finditer(pat, text):
            try:
                if fmt == "dmy":
                    d, m, y = int(match.group(1)), int(match.group(2)), int(match.group(3))
                elif fmt == "dmy2":
                    d, m, y = int(match.group(1)), int(match.group(2)), 2000 + int(match.group(3))
                else:
                    y, m, d = int(match.group(1)), int(match.group(2)), int(match.group(3))
                if 1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
                    return f"{y:04d}-{m:02d}-{d:02d}"
            except ValueError:
                continue
    return None


def line_has_exclusion(line_upper):
    for pat in EXCLUSION_PATTERNS:
        if re.search(pat, line_upper):
            return True
    return False


def line_has_tax_primary(line_upper):
    for pat in TAX_PRIMARY_PATTERNS:
        if re.search(pat, line_upper):
            return True
    return False


def extract_amount_from_line(line):
    matches = NUMBER_RE.findall(line)
    if not matches:
        return None
    val = matches[-1].replace(",", "")
    try:
        return float(val)
    except ValueError:
        return None


def truncate_at_gst_summary(lines):
    """Return lines up to (but not including) the GST SUMMARY header."""
    for i, line in enumerate(lines):
        if GST_SUMMARY_HEADER.search(line):
            return lines[:i]
    return lines


def extract_total_from_text(text):
    all_lines = text.split("\n")
    lines = truncate_at_gst_summary(all_lines)
    uppers = [ln.upper() for ln in lines]

    for group in PRIORITY_KEYWORDS:
        matched_indices = []
        for idx, u in enumerate(uppers):
            matched = False
            for pat in group:
                if re.search(pat, u):
                    matched = True
                    break
            if not matched:
                continue
            if line_has_exclusion(u):
                continue
            if line_has_tax_primary(u):
                continue
            matched_indices.append(idx)

        if not matched_indices:
            continue

        # Try last match first, then penultimate, etc. - the final total is usually
        # at the end. Also fall back to next line if no amount on matched line.
        for idx in reversed(matched_indices):
            amt = extract_amount_from_line(lines[idx])
            if amt is not None:
                return amt
